def main():
    import sys
    input = sys.stdin.read().split()
    s = input[1]
    n = len(s)
    count = 0

    for i in range(n):
        for j in range(i + 2, n + 1):
            substring = s[i:j]
            if substring == substring[::-1]:
                count += 1
    print(count)

